from collections import Counter

# Count dialogs per company
company_counts = Counter(d['company_id'] for d in dataset)
print("Total dialogs per company:")
for company, count in company_counts.most_common():
    print(f"  {company}: {count}")

# Let's first look for booking-related keywords
booking_keywords = ['booking', 'book', 'reservation', 'reserve', 'booked', 'flight booking']
booking_dialogs = {}

for d in dataset:
    dialog_lower = d['dialog'].lower()
    if any(kw in dialog_lower for kw in booking_keywords):
        company = d['company_id']
        if company not in booking_dialogs:
            booking_dialogs[company] = []
        booking_dialogs[company].append(d['dialog_id'])

print("\nDialogs with booking-related keywords per company:")
for company, ids in sorted(booking_dialogs.items(), key=lambda x: len(x[1]), reverse=True):
    print(f"  {company}: {len(ids)}")
